SELECT COUNT(*)
FROM CONSENT
WHERE CONSENT_TYPE = 'ACCOUNT'
  AND TARGET_ID = #{accountId}
  AND GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}

mapper.update:
UPDATE GYE_ACCOUNT
SET VERIFY_STATUS = 'VERIFIED',
    VERIFIED_BY = NULL,
    VERIFIED_AT = SYSDATE
WHERE GROUP_ID = #{groupId}
  AND GYE_ACCOUNT_ID = #{accountId}
  AND ACCOUNT_STATUS = 'PENDING'
  AND REQUESTED_AT IS NOT NULL
  AND CONFIRMED_AT IS NULL
  AND VERIFY_STATUS IN ('PENDING', 'REVERIFY_REQUIRED')
  AND ACCOUNT_NO_ENC = #{accountNoEnc}
  AND BANK_NAME = #{bankName}
  AND KEY_VER = #{keyVer}
